using System; using System.Text.RegularExpressions; using System.Web; using Newtonsoft.Json; using WillStrohl.API.oEmbed.Providers;

namespace WillStrohl.API.oEmbed { public sealed class Wrapper : ProviderBase { private const string URL_FORMAT="?url={0}&format={1}"; private const string FORMAT_PATTERN=@"\{format\}"; public string GetContent(RequestInfo r){var p=new ProviderFormat();if(!p.IsUrlSupported(r.URL))throw new ArgumentOutOfRangeException("URL","The specified URL is not supported by any existing OEmbed provider");switch(p.ProviderToUse(r.URL)){case Constants.PROVIDER_FLICKR:return new Flickr().GetPhoto(r.URL,r.MaxWidth,r.MaxHeight);case Constants.PROVIDER_HULU:return new Hulu().GetVideo(r.URL);case Constants.PROVIDER_QIK:return new Qik().GetVideo(r.URL);case Constants.PROVIDER_REVISION3:return new Revision3().GetVideo(r.URL);case Constants.PROVIDER_VIDDLER:return new Viddler().GetVideo(r.URL,r.MaxWidth,r.MaxHeight);case Constants.PROVIDER_VIMEO:return new Vimeo().GetVideo(r.URL);case Constants.PROVIDER_YOUTUBE:return new YouTube().GetVideo(r.URL);case Constants.PROVIDER_CLEARSPRINGWIDGETS:return new ClearspringWidgets().GetRichContent(r.URL);case Constants.PROVIDER_EMBEDLY:return new Embedly().GetRichContent(r.URL);case Constants.PROVIDER_MYOPERA:return new MyOpera().GetRichContent(r.URL);case Constants.PROVIDER_OOHEMBED:return new oohEmbed().GetRichContent(r.URL);case Constants.PROVIDER_POLLEVERYWHERE:return new PollEverywhere().GetRichContent(r.URL);default:throw new ArgumentOutOfRangeException("URL","The specified URL is not supported by any existing OEmbed provider");}} private string Parsed(string e,RequestInfo q,string[] a){string u;if(Regex.IsMatch(e,FORMAT_PATTERN)) {u=Regex.Replace(e,FORMAT_PATTERN,q.Format,RegexOptions.IgnoreCase);u+=e.Contains("?")?"&url=":"?url=";u+=HttpUtility.UrlEncode(q.URL);}else u=string.Concat(e,string.Format(URL_FORMAT,HttpUtility.UrlEncode(q.URL),q.Format));if(a!=null)foreach(string z in a)u+=z;return u;} public string GetPhotoContent(string e,RequestInfo q){return GetPhotoContent(e,q,null);}
 public string GetPhotoContent(string e,RequestInfo q,params string[] a){if(string.IsNullOrEmpty(e))throw new ArgumentNullException("EndPoint");if(q==null)throw new ArgumentNullException("Request");if(string.IsNullOrEmpty(q.URL))throw new ArgumentNullException("Request.URL");if(q.MaxHeight<=-1)throw new ArgumentNullException("Request.MaxHeight");if(q.MaxWidth<=-1)throw new ArgumentNullException("Request.MaxWidth");return ((PhotoInfo)JsonConvert.DeserializeObject(new RequestController().GetOEmbedContent(Parsed(e,q,a)),typeof(PhotoInfo))).Url;} public string GetVideoContent(string e,RequestInfo q){return GetVideoContent(e,q,null);}
 public string GetVideoContent(string e,RequestInfo q,params string[] a){return ((VideoInfo)JsonConvert.DeserializeObject(new RequestController().GetOEmbedContent(Parsed(e,q,a)),typeof(VideoInfo))).Html;} public string GetRichContent(string e,RequestInfo q){return GetRichContent(e,q,null);}
 public string GetRichContent(string e,RequestInfo q,params string[] a){return ((RichInfo)JsonConvert.DeserializeObject(new RequestController().GetOEmbedContent(Parsed(e,q,a)),typeof(RichInfo))).Html;} } }
